package com.bank.installment;

import java.util.*;
import java.util.logging.*;

public class BoxedDemo {
    private static final Logger log = Logger.getLogger("Installment");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        InstallmentService service = new InstallmentService();
        List<Integer> nums = service.installments(5);
        log.info(() -> "Installment numbers (List<Integer>): " + nums);
    }
}

// ─── Would be in service/InstallmentService.java ───
class InstallmentService {
    List<Integer> installments(int count) {
        return java.util.stream.IntStream.rangeClosed(1, count) // primitive, fast
            .map(n -> n)                                         // arithmetic stays primitive
            .boxed()                                             // IntStream → Stream<Integer>
            .collect(java.util.stream.Collectors.toList());      // now collectible
    }
}
